package fs

import (
	"context"
	"testing"
	"time"

	"go.uber.org/zap"
)

func TestPollerCloseWaitsForUpdate(t *testing.T) {
	started := make(chan struct{})
	release := make(chan struct{})
	finished := make(chan struct{})
	p := NewPoller(context.Background(), zap.NewNop(), func(ctx context.Context) (bool, error) {
		close(started)
		<-ctx.Done()
		<-release
		close(finished)
		return false, ctx.Err()
	}, WithInterval(time.Millisecond))
	go p.Poll()

	select {
	case <-started:
	case <-time.After(time.Second):
		t.Fatal("poll update did not start")
	}

	closed := make(chan struct{})
	go func() {
		_ = p.Close()
		close(closed)
	}()

	select {
	case <-p.ctx.Done():
	case <-time.After(time.Second):
		t.Fatal("poll context was not cancelled")
	}
	select {
	case <-closed:
		t.Fatal("Close returned before the update finished")
	default:
	}

	close(release)
	select {
	case <-closed:
	case <-time.After(time.Second):
		t.Fatal("Close did not wait for the poll loop to exit")
	}
	select {
	case <-finished:
	default:
		t.Fatal("update was still running after Close returned")
	}
	if err := p.Close(); err != nil {
		t.Fatal(err)
	}
}

func TestPollerCloseBeforeStart(t *testing.T) {
	p := NewPoller(context.Background(), zap.NewNop(), func(context.Context) (bool, error) {
		t.Fatal("update called after Close")
		return false, nil
	})
	if err := p.Close(); err != nil {
		t.Fatal(err)
	}
	p.Poll()
}
